// Deterministic random.
//
// Phase 4 upgrade: xorshift128+ instead of forwarding to
// UnityEngine.Random. Xorshift128+ is fast, has a period of 2^128 − 1,
// passes standard PRNG test suites, and produces byte-identical
// sequences from the same seed on every platform.
//
// Callers always go through the static shim so upgrading the algorithm
// (or seeding scheme) is a one-file change.
//
// The lockstep bootstrap in Phase 5 will call Seed() with a shared
// ulong generated by the host at StartGame and broadcast to all peers.

using System;

namespace LifeIsAGame.DetSim
{
    public static class DetRandom
    {
        // xorshift128+ state — two 64-bit words.
        private static ulong _s0 = 0x9E3779B97F4A7C15UL;
        private static ulong _s1 = 0xBF58476D1CE4E5B9UL;

        /// <summary>Reseed both state words deterministically from a single seed.</summary>
        public static void Seed(ulong seed)
        {
            // SplitMix64 the seed into two well-mixed state words.
            _s0 = SplitMix64(ref seed);
            _s1 = SplitMix64(ref seed);
            // xorshift128+ requires at least one non-zero word.
            if ((_s0 | _s1) == 0UL) _s1 = 1UL;
        }

        /// <summary>Legacy overload matching the Phase 1 shim signature.</summary>
        public static void Seed(int seed) => Seed(unchecked((ulong)seed));

        /// <summary>Uniform 64-bit unsigned. Underlying primitive.</summary>
        public static ulong NextUInt64()
        {
            ulong s1 = _s0;
            ulong s0 = _s1;
            _s0 = s0;
            s1 ^= s1 << 23;
            _s1 = s1 ^ s0 ^ (s1 >> 17) ^ (s0 >> 26);
            return unchecked(_s1 + s0);
        }

        /// <summary>Uniform int in [min, max) — half-open, Unity convention.</summary>
        public static int Range(int min, int max)
        {
            if (min >= max) return min;
            ulong span = (ulong)(max - min);
            return min + (int)(NextUInt64() % span);
        }

        /// <summary>Uniform float in [min, max). Converts through Fix64 so the sequence stays deterministic.</summary>
        public static float Range(float min, float max)
        {
            // Use the top 32 bits of the u64 as a Fix64 fractional in [0, 1),
            // then linear-interpolate. Determinism: xorshift + integer ops.
            uint top32 = (uint)(NextUInt64() >> 32);
            // Q1.31-ish -> Fix64 fractional. We shift by 1 so we don't hit
            // exactly 1.0 (Fix64.ONE_RAW), preserving the half-open range.
            Fix64 t = Fix64.FromRaw((long)top32 << 1);
            Fix64 lo = Fix64.FromFloat(min);
            Fix64 hi = Fix64.FromFloat(max);
            return (lo + (hi - lo) * t).ToFloat();
        }

        /// <summary>Uniform Fix64 in [0, 1).</summary>
        public static Fix64 UnitFix64()
        {
            uint top32 = (uint)(NextUInt64() >> 32);
            return Fix64.FromRaw((long)top32 << 1);
        }

        // -----------------------------------------------------------------
        // Internal
        // -----------------------------------------------------------------

        private static ulong SplitMix64(ref ulong x)
        {
            unchecked
            {
                x += 0x9E3779B97F4A7C15UL;
                ulong z = x;
                z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
                z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
                return z ^ (z >> 31);
            }
        }
    }
}
